/**
 * Shotgun Formation — player avatars.
 *
 * Ten football characters cut from the game's own art, one per drinking action.
 * The physical box says 3–10 players, so a full table gets ten distinct faces.
 *
 * ⚠️  Nothing may hardcode the number 10. Derive it from AVATARS.length so a
 *     future sheet with more characters drops in with no other edits.
 */

export const AVATARS = [
  { id: 'shotgun', label: 'Shotgun', ring: '#7FB2FF', src: 'data:image/png;base64,' },
  { id: 'beerbong', label: 'Beer Bong', ring: '#FF8FB1', src: 'data:image/png;base64,' },
  { id: 'doublefist', label: 'Double Fist', ring: '#7BE0D6', src: 'data:image/png;base64,' },
  { id: 'kegstand', label: 'Keg Stand', ring: '#C7A0FF', src: 'data:image/png;base64,' },
  { id: 'partybucket', label: 'Party Bucket', ring: '#FFD166', src: 'data:image/png;base64,' },
  { id: 'chugger', label: 'Chugger', ring: '#9BE07B', src: 'data:image/png;base64,' },
  { id: 'tailgate', label: 'Tailgate Toast', ring: '#FF9E6B', src: 'data:image/png;base64,' },
  { id: 'beersplash', label: 'Beer Splash', ring: '#8FD3FF', src: 'data:image/png;base64,' },
  { id: 'funnel', label: 'Funnel Force', ring: '#E0A3C9', src: 'data:image/png;base64,' },
  { id: 'victorypour', label: 'Victory Pour', ring: '#B8C4D9', src: 'data:image/png;base64,' },
];

/**
 * The ring palette, derived from the sheet so it grows with it. These are the
 * only colours allowed for player identity: amber, neon and red are reserved
 * for deck semantics (Standard / Wild / the 40-drink cards).
 */
export const RING_COLORS = AVATARS.map((a) => a.ring);

/** Stable, case- and whitespace-insensitive hash of a player name. */
export function hashName(name) {
  const s = String(name || '').trim().toLowerCase();
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return Math.abs(h);
}

/**
 * Assign an avatar to every player, deterministic by name.
 * No two players share a character while there are enough to go round; past that
 * the ring colour is what keeps them apart.
 *
 * @param {Array<{name:string}>} players
 * @returns {Object} name -> { ...avatar, ringIndex }
 */
export function assignAvatars(players = []) {
  const n = AVATARS.length;
  const taken = new Set();
  /** avatar index -> ring indices already handed out for that character */
  const ringsUsed = new Map();
  const out = {};
  [...players]
    .sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || '')))
    .forEach((p) => {
      const key = String(p?.name || '');
      const h = hashName(key);

      // Character: your own hash first, stepping on only if someone already
      // has that one.
      let idx = h % n;
      for (let step = 0; step < n && taken.has(idx); step++) idx = (idx + 1) % n;
      if (taken.size < n) taken.add(idx);

      // Ring: also your own hash first, but stepped on until it is unique
      // AMONG THE PLAYERS SHARING THIS CHARACTER. Hashing the ring
      // independently was not enough — two players could collide on the
      // character and the ring at once, which is precisely the case the ring
      // exists to prevent (13 players, 10 characters: Player9 and Player13
      // both landed on Victory Pour with the same ring).
      const used = ringsUsed.get(idx) || new Set();
      let ring = (h >> 5) % n;
      for (let step = 0; step < n && used.has(ring); step++) ring = (ring + 1) % n;
      used.add(ring);
      ringsUsed.set(idx, used);

      out[key] = { ...AVATARS[idx], index: idx, ring: RING_COLORS[ring], ringIndex: ring };
    });
  return out;
}

/** Single-player lookup when the roster isn't to hand. Prefer assignAvatars. */
export function avatarFor(name) {
  const a = AVATARS[hashName(name) % AVATARS.length];
  return { ...a, ring: AVATARS[(hashName(name) >> 5) % AVATARS.length].ring };
}

export default AVATARS;